def transform(grid):
    n=len(grid)
    cw=[list(row) for row in zip(*grid[::-1])]
    ccw=[list(row) for row in zip(*grid)][::-1]
    r180=[row[::-1] for row in grid[::-1]]
    return [grid[i]+cw[i] for i in range(n)] + [ccw[i]+r180[i] for i in range(n)]
